const String _cuanPalaceBgBase64 = '';

const _roomPurple = Color(0xFF7A3CFF);
const _roomGold = Color(0xFFFFD66B);

final ValueNotifier<int> coinBalance = ValueNotifier<int>(0);
final ValueNotifier<int> diamondBalance = ValueNotifier<int>(0);

enum _RoomEventType { chat, gift }

class _RoomEvent {
  final _RoomEventType type;
  final String from;
  final String text;
  final String? to;
  final int coinCost;

  const _RoomEvent.chat(this.from, this.text)
      : type = _RoomEventType.chat,
        to = null,
        coinCost = 0;

  const _RoomEvent.gift(this.from, this.to, this.text, this.coinCost)
      : type = _RoomEventType.gift;
}

final ValueNotifier<List<_RoomEvent>> roomEvents = ValueNotifier<List<_RoomEvent>>([]);

void _addRoomEvent(_RoomEvent event) {
  roomEvents.value = [...roomEvents.value, event];
}

void _setCoins(int value) {
  coinBalance.value = value < 0 ? 0 : value;
}

void _addCoins(int value) {
  _setCoins(coinBalance.value + value);
}

void _setDiamonds(int value) {
  diamondBalance.value = value < 0 ? 0 : value;
}

void _addDiamonds(int value) {
  _setDiamonds(diamondBalance.value + value);
}

final ValueNotifier<List<String>> walletTransactions = ValueNotifier<List<String>>([]);

void _addWalletTransaction(String text) {
  walletTransactions.value = [text, ...walletTransactions.value];
}

void _recharge(int coins) {
  _addCoins(coins);
  _addWalletTransaction('Isi Saldo +${_formatCoins(coins)} Coin');
}

class _C {
  static const bg = Color(0xFFE8D1A6);
  static const surface = Color(0xFFFFFBF4);
  static const surface2 = Color(0xFFF3E7D4);
  static const brown = Color(0xFF5B3A20);
  static const brown2 = Color(0xFF7B5632);
  static const gold = Color(0xFFC89B4A);
  static const gold2 = Color(0xFFE8C979);
  static const line = Color(0xFFE5D6BE);
  static const text = Color(0xFF3E2B1D);
  static const muted = Color(0xFF8D7A68);
}

enum _LevelTier {
  tier1,
  tier2,
  tier3,
  tier4,
  tier5,
  tier6,
}

_LevelTier _getLevelTier(int level) {
  if (level <= 20) return _LevelTier.tier1;
  if (level <= 40) return _LevelTier.tier2;
  if (level <= 60) return _LevelTier.tier3;
  if (level <= 80) return _LevelTier.tier4;
  if (level <= 100) return _LevelTier.tier5;
  return _LevelTier.tier6;
}
Color _getLevelTierColor(int level) {
  switch (_getLevelTier(level)) {
    case _LevelTier.tier1:
      return const Color(0xFFD4AF37);
    case _LevelTier.tier2:
      return const Color(0xFFE8C97A);
    case _LevelTier.tier3:
      return const Color(0xFFB89B5E);
    case _LevelTier.tier4:
      return const Color(0xFFC0C0C0);
    case _LevelTier.tier5:
      return const Color(0xFF9E7B3C);
    case _LevelTier.tier6:
      return const Color(0xFFFFD76A);
  }
}
