class _DefaultAvatarFramePainter extends CustomPainter {
  const _DefaultAvatarFramePainter();

  @override
  void paint(Canvas canvas, Size size) {
    final c = size.center(Offset.zero);
    final r = size.width * .335;
    final gold = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 7
      ..shader = const LinearGradient(
        colors: [Color(0xFFFFF0A8), Color(0xFFC27A18), Color(0xFFFFE9A0), Color(0xFF9A5B10)],
      ).createShader(Offset.zero & size);

    canvas.drawCircle(c, r + 15, gold);
    canvas.drawCircle(c, r + 22, Paint()..color = const Color(0xFFE7B34B)..style = PaintingStyle.stroke..strokeWidth = 2);

    final wing = Paint()..color = const Color(0xFFF8F1DE)..style = PaintingStyle.fill;
    final edge = Paint()..color = const Color(0xFFD59A32)..style = PaintingStyle.stroke..strokeWidth = 1.5;
    for (final side in [-1, 1]) {
      final p = Path()
        ..moveTo(c.dx + side * (r + 6), c.dy + 12)
        ..cubicTo(c.dx + side * (r + 40), c.dy - 6, c.dx + side * (r + 48), c.dy - 32, c.dx + side * (r + 42), c.dy - 54)
        ..cubicTo(c.dx + side * (r + 34), c.dy - 39, c.dx + side * (r + 24), c.dy - 25, c.dx + side * (r + 10), c.dy - 12)
        ..close();
      canvas.drawPath(p, wing);
      canvas.drawPath(p, edge);
    }

    final crown = Paint()..color = const Color(0xFFFFD86C)..style = PaintingStyle.fill;
    final cp = Path()
      ..moveTo(c.dx - 31, c.dy - r - 24)
      ..lineTo(c.dx - 20, c.dy - r - 5)
      ..lineTo(c.dx - 8, c.dy - r - 20)
      ..lineTo(c.dx, c.dy - r - 2)
      ..lineTo(c.dx + 10, c.dy - r - 20)
      ..lineTo(c.dx + 22, c.dy - r - 5)
      ..lineTo(c.dx + 32, c.dy - r - 24)
      ..lineTo(c.dx + 28, c.dy - r + 2)
      ..lineTo(c.dx - 28, c.dy - r + 2)
      ..close();
    canvas.drawPath(cp, crown);
    canvas.drawPath(cp, Paint()..color = const Color(0xFF9D6415)..style = PaintingStyle.stroke..strokeWidth = 1.5);
    canvas.drawCircle(Offset(c.dx, c.dy + r + 16), 9, Paint()..color = const Color(0xFF8D39B5));
    canvas.drawCircle(Offset(c.dx, c.dy + r + 16), 9, Paint()..color = const Color(0xFFFFE58A)..style = PaintingStyle.stroke..strokeWidth = 2);
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}


