class _LuxuryPanelOrnamentPainter extends CustomPainter {
  const _LuxuryPanelOrnamentPainter();
  @override
  void paint(Canvas canvas, Size size) {
    final p = Paint()..color = const Color(0xFFD6A23A)..style = PaintingStyle.stroke..strokeWidth = 1;
    final diamond = Path()
      ..moveTo(size.width/2, 0)..lineTo(size.width/2 + 7, 7)
      ..lineTo(size.width/2, 14)..lineTo(size.width/2 - 7, 7)..close();
    canvas.drawPath(diamond, p);
    canvas.drawPath(diamond.shift(Offset(0, size.height-14)), p);
    for (final x in [8.0, size.width-8]) {
      canvas.drawCircle(Offset(x, 9), 2.5, Paint()..color = const Color(0xFFD6A23A));
      canvas.drawCircle(Offset(x, size.height-9), 2.5, Paint()..color = const Color(0xFFD6A23A));
    }
  }
  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

