class _BadgeEmblem extends StatelessWidget {
  final int variant;
  const _BadgeEmblem({required this.variant});
  @override
  Widget build(BuildContext context) {
    const jewel = [Color(0xFFD02A2A),Color(0xFF2F6BC3),Color(0xFFE72B86),Color(0xFFD97A1A),Color(0xFF7044C5),Color(0xFF2C7FE2),Color(0xFF14956D),Color(0xFF416FAE),Color(0xFFD58A21),Color(0xFF7A42B7)];
    final c=jewel[variant%jewel.length];
