class _BadgeArtworkPainter extends CustomPainter {
  final Color c; final int variant;
  const _BadgeArtworkPainter(this.c,this.variant);
  @override void paint(Canvas canvas,Size size){
    final center=Offset(size.width/2,size.height/2);
    final laurel=Paint()..color=const Color(0xFFD7A33D)..style=PaintingStyle.stroke..strokeWidth=2.3;
    for(final side in [-1,1]){
      final p=Path()..moveTo(center.dx+side*6,center.dy+19)..quadraticBezierTo(center.dx+side*25,center.dy+6,center.dx+side*18,center.dy-18);
      canvas.drawPath(p,laurel);
    }
    final outer=Paint()..shader=LinearGradient(colors:[const Color(0xFFFFE8A1),const Color(0xFFD18B18),const Color(0xFFFFF2BC)]).createShader(Rect.fromCircle(center:center,radius:21));
    canvas.drawCircle(center,21,outer);
    canvas.drawCircle(center,17,Paint()..color=c);
    canvas.drawCircle(center,17,Paint()..style=PaintingStyle.stroke..strokeWidth=1.2..color=const Color(0xFFFFE6A0));
    final icon=Paint()..color=Colors.white..style=PaintingStyle.stroke..strokeWidth=2.3..strokeCap=StrokeCap.round;
    final path=Path()..moveTo(center.dx,center.dy-9)..lineTo(center.dx+9,center.dy-2)..lineTo(center.dx+6,center.dy+10)..lineTo(center.dx,center.dy+14)..lineTo(center.dx-6,center.dy+10)..lineTo(center.dx-9,center.dy-2)..close();
    canvas.drawPath(path,icon);
    canvas.drawCircle(Offset(center.dx,center.dy+2),3.2,Paint()..color=const Color(0xFFFFE9A0));
  }
  @override bool shouldRepaint(covariant _BadgeArtworkPainter oldDelegate)=>oldDelegate.c!=c||oldDelegate.variant!=variant;
}

