class _LevelMedallionPainter extends CustomPainter {
  final Color accent;
  final String kind;
  const _LevelMedallionPainter({required this.accent, required this.kind});

  @override
  void paint(Canvas canvas, Size size) {
    final c = Offset(size.width / 2, size.height / 2);
    final r = size.width * .43;

    final shadow = Paint()..color = const Color(0x5545280A);
    canvas.drawCircle(c.translate(0, 2), r + 2, shadow);

    final outer = Paint()
      ..shader = const RadialGradient(colors: [Color(0xFFFFF4B7), Color(0xFFD89B21), Color(0xFF8B4D0B)])
          .createShader(Rect.fromCircle(center: c, radius: r + 2));
    canvas.drawCircle(c, r + 2, outer);

    final ring = Paint()
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2.2
      ..color = const Color(0xFFFFE9A0);
    canvas.drawCircle(c, r - 2, ring);

    final inner = Paint()..color = accent;
    canvas.drawCircle(c, r * .70, inner);
    canvas.drawCircle(c, r * .70, Paint()..style = PaintingStyle.stroke..strokeWidth = 1.5..color = const Color(0xFFFFE39A));

    final white = Paint()..color = Colors.white;
    if (kind == 'WEALTH') {
      _drawCrown(canvas, c, white);
    } else if (kind == 'CHARM') {
      _drawHeart(canvas, c, white);
    } else {
      _drawController(canvas, c, white);
    }
  }

  void _drawCrown(Canvas canvas, Offset c, Paint p) {
    final path = Path()
      ..moveTo(c.dx-24,c.dy+13)..lineTo(c.dx-20,c.dy-12)..lineTo(c.dx-8,c.dy-2)
      ..lineTo(c.dx,c.dy-20)..lineTo(c.dx+8,c.dy-2)..lineTo(c.dx+20,c.dy-12)
      ..lineTo(c.dx+24,c.dy+13)..close();
    canvas.drawPath(path, p..style=PaintingStyle.fill);
    canvas.drawLine(Offset(c.dx-20,c.dy+15), Offset(c.dx+20,c.dy+15), p..strokeWidth=4..strokeCap=StrokeCap.round);
  }

  void _drawHeart(Canvas canvas, Offset c, Paint p) {
    final path = Path()..moveTo(c.dx,c.dy+22)
      ..cubicTo(c.dx-38,c.dy-2,c.dx-20,c.dy-25,c.dx,c.dy-9)
      ..cubicTo(c.dx+20,c.dy-25,c.dx+38,c.dy-2,c.dx,c.dy+22)..close();
    canvas.drawPath(path, p);
  }

  void _drawController(Canvas canvas, Offset c, Paint p) {
    final body = RRect.fromRectAndRadius(Rect.fromCenter(center: c.translate(0,3), width: 48, height: 27), const Radius.circular(10));
    canvas.drawRRect(body, p..style=PaintingStyle.fill);
    final dark = Paint()..color = accent;
    canvas.drawCircle(Offset(c.dx-12,c.dy+3),3,dark); canvas.drawCircle(Offset(c.dx+12,c.dy+3),3,dark);
    final line = Paint()..color = accent..strokeWidth=3..strokeCap=StrokeCap.round;
    canvas.drawLine(Offset(c.dx-19,c.dy+3),Offset(c.dx-7,c.dy+3),line);
    canvas.drawLine(Offset(c.dx-13,c.dy-3),Offset(c.dx-13,c.dy+9),line);
    canvas.drawCircle(Offset(c.dx+12,c.dy-2),2.3,dark); canvas.drawCircle(Offset(c.dx+18,c.dy+4),2.3,dark);
  }

  @override
  bool shouldRepaint(covariant _LevelMedallionPainter oldDelegate) => oldDelegate.accent != accent || oldDelegate.kind != kind;
}

