class EditProfilePage extends StatefulWidget {
  const EditProfilePage({super.key});

  @override
  State<EditProfilePage> createState() => _EditProfilePageState();
}

class _EditProfilePageState extends State<EditProfilePage> {
  late final TextEditingController _name;
  late final TextEditingController _age;
  late final TextEditingController _country;
  late final TextEditingController _bio;

  late String _gender;

  @override
  void initState() {
    super.initState();
    _name = TextEditingController(text: AppProfileState.name.value);
    _age = TextEditingController(text: AppProfileState.age.value);
    _country = TextEditingController(text: AppProfileState.country.value);
    _bio = TextEditingController(text: AppProfileState.bio.value);
    _gender = AppProfileState.gender.value;
  }

  @override
  void dispose() {
    _name.dispose();
    _age.dispose();
    _country.dispose();
    _bio.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return _SubPage(
      title: 'Edit Profil',
      child: ListView(
        padding: const EdgeInsets.all(20),
        children: [
          Center(
            child: CircleAvatar(
              radius: 54,
              backgroundColor: _C.gold2,
              child: const Icon(
                Icons.person,
                color: _C.brown,
                size: 60,
              ),
            ),
          ),
          const SizedBox(height: 22),
          _editField('Nama', _name),
          _editField(
            'Umur',
            _age,
            keyboard: TextInputType.number,
          ),
          Padding(
            padding: const EdgeInsets.only(bottom: 12),
            child: DropdownButtonFormField<String>(
              value: _gender,
              decoration: const InputDecoration(
                labelText: 'Jenis Kelamin',
                border: OutlineInputBorder(),
              ),
              items: const [
                DropdownMenuItem(
                  value: 'Laki-laki',
                  child: Text('Laki-laki'),
                ),
                DropdownMenuItem(
                  value: 'Perempuan',
                  child: Text('Perempuan'),
                ),
              ],
              onChanged: (value) {
                if (value != null) {
                  setState(() => _gender = value);
                }
              },
            ),
          ),
          _editField('Negara', _country),
          _editField(
            'Bio',
            _bio,
            maxLines: 4,
          ),
          const SizedBox(height: 12),
          SizedBox(
            height: 52,
            child: FilledButton(
              style: FilledButton.styleFrom(
                backgroundColor: _C.brown,
                foregroundColor: Colors.white,
              ),
              onPressed: () async {
                final newName = _name.text.trim();
                if (newName.isEmpty) {
                  _showMessage(context, 'Nama tidak boleh kosong.');
                  return;
                }
                final uid = FirebaseAuth.instance.currentUser?.uid;
                if (uid == null) {
                  _showMessage(context, 'Sesi login tidak tersedia.');
                  return;
                }
                try {
                  final currentUser = FirebaseAuth.instance.currentUser;
                  await FirebaseFirestore.instance.collection('users').doc(uid).set({
                    'displayName': newName,
                    'age': _age.text.trim(),
                    'country': _country.text.trim(),
                    'bio': _bio.text.trim(),
                    'gender': _gender,
                    'updatedAt': FieldValue.serverTimestamp(),
                  }, SetOptions(merge: true));

                  if (currentUser != null && currentUser.displayName != newName) {
                    await currentUser.updateDisplayName(newName);
                  }

                  AppProfileState.name.value = newName;
                  AppProfileState.age.value = _age.text.trim();
                  AppProfileState.country.value = _country.text.trim();
                  AppProfileState.bio.value = _bio.text.trim();
                  AppProfileState.gender.value = _gender;
                  if (!mounted) return;
                  Navigator.pop(context);
                  _showMessage(context, 'Profil berhasil disimpan.');
                } on FirebaseException catch (e) {
                  if (mounted) {
                    _showMessage(
                      context,
                      'Gagal menyimpan profil: ${e.code}',
                    );
                  }
                } catch (e) {
                  if (mounted) {
                    _showMessage(context, 'Gagal menyimpan profil: $e');
                  }
                }
              },
              child: const Text(
                'SAVE',
                style: TextStyle(
                  fontWeight: FontWeight.w900,
                  letterSpacing: 1,
                ),
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _editField(
    String label,
    TextEditingController controller, {
    TextInputType? keyboard,
    int maxLines = 1,
  }) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: TextField(
        controller: controller,
        keyboardType: keyboard,
        maxLines: maxLines,
        style: const TextStyle(color: _C.text, fontWeight: FontWeight.w700),
        decoration: InputDecoration(
          labelText: label,
          labelStyle: const TextStyle(color: _C.brown, fontWeight: FontWeight.w700),
          floatingLabelStyle: const TextStyle(color: _C.brown, fontWeight: FontWeight.w900),
          filled: true,
          fillColor: const Color(0xFFF8EEDB),
          border: OutlineInputBorder(borderRadius: BorderRadius.circular(14), borderSide: BorderSide(color: _C.gold)),
          enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(14), borderSide: BorderSide(color: _C.gold.withOpacity(.65))),
          focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(14), borderSide: BorderSide(color: _C.brown, width: 1.5)),
        ),
      ),
    );
  }
}

void _showSettingsDialog(BuildContext context, String title, String message) {
  showDialog(
    context: context,
